sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        CustomEvent.observe('x_hsb11_mss_c_proc.msscustodyTaskFormRel', function(recordID) {
            var reloadWindow = true;
            g_form.reloadWindow(reloadWindow);
            return;
        });
        if (g_form.getValue('position_attribute_sync') != 'Attribute Sync is in progress') {
            //Reload the task form to reflect the changes that form is editable back when Swift attribute value changes to success or error
            if (newValue === 'Response Success-All fields updated(200)' || newValue === 'Response Un-Successful - Error') {
                //location.reload();
                CustomEvent.observe('x_hsb11_mss_c_proc.msscustodyTaskFormRel', function(recordID) {
                    var reloadWindow = true;
                    g_form.reloadWindow(reloadWindow);
                    return;
                });

            }
        }
    }
